'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id = () => crypto.randomUUID();
let groups = [], snapshots = [], presets = [], batches = [], trash = [], tabs = [], view = 'open', selected = new Set(), bulkSelected = new Set(), query = '', toastTimer;
const dashboardUrl = chrome.runtime.getURL('dashboard.html');
const isDashboard = u => typeof u==='string' && u.split(/[?#]/,1)[0]===dashboardUrl;
const validUrl = u => /^https?:\/\//i.test(u || '');
function timeLabel(value){const t=TimeTools.format(value);return t?`<time datetime="${esc(t.iso)}" title="${esc(t.full)}" data-full="${esc(t.full)}" aria-label="${esc(t.full)}" tabindex="0">${esc(t.short)}</time>`:'Không rõ';}
function notify(msg){const el=$('#toast');el.textContent=msg;el.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hidden'),5000)}
async function load(){ const result=await chrome.storage.local.get(null); trash=Object.entries(result).filter(([k,v])=>k.startsWith(TrashTools.prefix)&&v&&v.value).map(([,v])=>v).sort((a,b)=>b.deletedAt-a.deletedAt); batches=Object.entries(result).filter(([k,v])=>k.startsWith(BatchTools.prefix)&&v&&Array.isArray(v.items)).map(([,v])=>v).sort((a,b)=>b.createdAt-a.createdAt); groups=Array.isArray(result.groups)?result.groups:[]; snapshots=Array.isArray(result.snapshots)?result.snapshots:[]; presets=Array.isArray(result.presets)?result.presets:[]; tabs=(await chrome.tabs.query({})).filter(t=>!t.incognito&&!isDashboard(t.url)); selected=new Set([...selected].filter(id=>tabs.some(t=>t.id===id))); render(); }
async function persist(){await chrome.storage.local.set({groups});}
function inbox(){let g=groups.find(x=>x.id==='inbox');if(!g){g={id:'inbox',name:'Để sau',icon:'✦',color:'#7771df',createdAt:Date.now(),items:[]};groups.unshift(g)}return g}
function showDialog(html, handler){$('#dialogBody').innerHTML=html;const d=$('#dialog');const cancel=$('#dialogBody').querySelector('button[value=cancel]');if(cancel)cancel.formNoValidate=true;d.showModal();let busy=false;d.oncancel=e=>{if(busy)e.preventDefault()};$('#dialogForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const submit=e.submitter;if(submit?.value==='cancel'){d.close();return}busy=true;if(submit)submit.disabled=true;try{await handler(new FormData(e.currentTarget),d); }catch(err){notify('Không thể thực hiện: '+err.message)}finally{busy=false;if(submit)submit.disabled=false}};}
function groupDialog(existing){showDialog(`<h2>${existing?'Chỉnh sửa nhóm':'Tạo nhóm mới'}</h2><p>Gom những trang quan trọng vào một nơi của riêng bạn.</p><label class="field">Tên nhóm<input name="name" required maxlength="80" value="${esc(existing?.name||'')}" placeholder="Ví dụ: Công việc"></label><label class="field">Biểu tượng<select name="icon">${['✦','◈','▣','✳','☼','♡','⌘','◉','✿'].map(x=>`<option ${existing?.icon===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Tag nhóm <small>(phân cách bằng dấu phẩy)</small><input name="tags" value="${esc((existing?.tags||[]).join(', '))}" placeholder="công việc, thiết kế"></label><label class="field">Màu nhóm<input type="color" name="color" value="${esc(existing?.color||'#7564d6')}"></label><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">${existing?'Lưu thay đổi':'Tạo nhóm'}</button></div>`,async(f,d)=>{const name=String(f.get('name')).trim();if(!name)throw Error('Vui lòng nhập tên nhóm.');const latest=await chrome.storage.local.get('groups');const list=latest.groups||[];if(existing){const current=list.find(g=>g.id===existing.id);if(!current)throw Error('Nhóm không còn tồn tại.');current.name=name;current.icon=f.get('icon');current.color=f.get('color');current.tags=OrganizeTools.tags(f.get('tags'))}else list.push({id:id(),name,icon:f.get('icon'),color:f.get('color'),tags:OrganizeTools.tags(f.get('tags')),createdAt:Date.now(),items:[]});await chrome.storage.local.set({groups:list});d.close();await load();notify(existing?'Đã cập nhật nhóm.':'Đã tạo nhóm mới.')})}
function validTabs(){return tabs.filter(t=>selected.has(t.id) && validUrl(t.url))}
function saveDialog(closeAfter){let list=validTabs();if(!list.length){notify('Hãy chọn ít nhất một trang web http hoặc https.');return}const choices=groups.some(g=>g.id==='inbox')?groups:[{id:'inbox',name:'Để sau',icon:'✦'},...groups];const skipped=tabs.filter(t=>selected.has(t.id)&&!validUrl(t.url)).length;showDialog(`<h2>${closeAfter?'Lưu & đóng tab':'Lưu tab đã chọn'}</h2><p>${closeAfter?'Tab sẽ được lưu trước khi đóng. Nội dung chưa lưu trên trang có thể bị mất.':'Tạo bản sao trong nhóm; tab đang mở sẽ không thay đổi.'} ${skipped?`<b>${skipped} tab không hỗ trợ sẽ bỏ qua.</b>`:''}</p><label class="field">Lưu vào nhóm<select name="group">${choices.map(g=>`<option value="${esc(g.id)}">${esc(g.icon)} ${esc(g.name)}</option>`).join('')}</select></label><div class="dialoglist">${list.map(t=>`<div>• ${esc(t.title||t.url)}</div>`).join('')}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="${closeAfter?'danger-soft':'primary'}">${closeAfter?'Lưu & đóng':'Lưu bản sao'} (${list.length})</button></div>`,async(f,d)=>{const target=f.get('group')==='inbox'?inbox():groups.find(g=>g.id===f.get('group'));if(!target)throw Error('Nhóm không còn tồn tại.');let prepared=[];let skippedCount=0;for(const t of list){try{const current=await chrome.tabs.get(t.id);if(current.url!==t.url||!validUrl(current.url)){skippedCount++;continue}prepared.push({tabId:t.id,url:current.url,item:{id:id(),url:current.url,title:current.title||current.url,createdAt:Date.now(),tags:[]}})}catch{skippedCount++}}if(!prepared.length)throw Error('Các tab đã thay đổi hoặc không còn mở.');target.items.unshift(...prepared.map(x=>x.item));try{await persist()}catch(e){target.items.splice(0,prepared.length);throw e}let result;if(closeAfter){try{result=await BatchTools.closeSaved(chrome,prepared,'Lưu & đóng thủ công',id,()=>true)}catch(e){d.close();await load();notify('Đã lưu tab nhưng không thể ghi lịch sử; không đóng tab nào.');return}}selected.clear();d.close();await load();const closed=result?.batch.items.filter(x=>x.status==='closed').length||0;notify(closeAfter?`Đã lưu ${prepared.length} tab, đóng ${closed}. ${result.stopped?'Lượt dọn bị gián đoạn; xem Lịch sử dọn.':`Xem chi tiết tại Lịch sử dọn.${skippedCount?` Bỏ qua ${skippedCount} tab đã thay đổi.`:''}`}`:`Đã lưu ${prepared.length} tab.${skippedCount?` Bỏ qua ${skippedCount} tab đã thay đổi.`:''}`)})}
function matches(...values){return values.some(v=>String(v||'').toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi')))}
function rowTab(t,extra=''){const host=(()=>{try{return new URL(t.url).hostname||t.url}catch{return t.url||'Trang bị hạn chế'}})();return `<div class="row"><input type="checkbox" data-select="${t.id}" aria-label="Chọn ${esc(t.title)}" ${selected.has(t.id)?'checked':''}><div class="favicon">${t.favIconUrl&&/^https?:|^data:/i.test(t.favIconUrl)?`<img src="${esc(t.favIconUrl)}" alt="">`:'◈'}</div><div class="rowtext"><div class="rowtitle">${esc(t.title||t.url||'Tab không có tiêu đề')}</div><div class="rowurl">${esc(host)} · ${esc(t.url||'Không có URL')}${extra?' · '+esc(extra):''}</div></div><div class="badges">${t.active?'<span class="badge">Đang xem</span>':''}${t.pinned?'<span class="badge">Đã ghim</span>':''}${t.audible?'<span class="badge">Có âm thanh</span>':''}${t.discarded?'<span class="badge">Đã nghỉ</span>':''}</div><div class="rowactions"><button data-action="switch" data-id="${t.id}">Đến tab ↗</button><button data-action="discard" data-id="${t.id}" title="Cho tab nghỉ">Nghỉ</button><button data-action="close" data-id="${t.id}" title="Đóng tab">✕</button></div></div>`}
function renderOpen(){let visible=tabs.filter(t=>matches(t.title,t.url));let windows=[...new Set(visible.map(t=>t.windowId))];$('#contentArea').innerHTML=windows.length?windows.map((w,i)=>{let ts=visible.filter(t=>t.windowId===w);return `<div class="sectionhead"><div><h2>Cửa sổ ${i+1}</h2><p>Các tab đang mở trong cửa sổ này</p></div><span class="sectioncount">${ts.length} tab</span></div><div class="card">${ts.map(rowTab).join('')}</div>`}).join(''):'<div class="empty"><b>Không tìm thấy tab nào</b>Thử từ khóa khác hoặc mở một trang mới.</div>'}
function renderDuplicates(){
 const windowIds=[...new Set(tabs.map(t=>t.windowId))];
 const all=DuplicateTools.find(tabs);const visible=all.filter(g=>matches(g.url,...g.tabs.map(t=>t.title)));
 const info=`<div class="session-intro"><div><b>Kiểm tra trước khi dọn</b><p>Chỉ so sánh URL web giống hệt nhau, bao gồm query và fragment. Các tab có thể chứa trạng thái khác nhau. Không có tab nào được chọn tự động.</p></div></div>`;
 $('#contentArea').innerHTML=info+(visible.length?visible.map(g=>`<div class="sectionhead"><div><h2>${esc(g.tabs[0].title||g.url)}</h2><p>${esc(g.url)}</p></div><span class="sectioncount">${g.tabs.length} tab</span></div><div class="card">${g.tabs.map(t=>rowTab(t,`Cửa sổ ${windowIds.indexOf(t.windowId)+1}`)).join('')}</div>`).join(''):'<div class="empty"><b>Không có tab trùng phù hợp</b>Chỉ các tab http/https có URL giống hệt mới được liệt kê.</div>');
}

function renderSaved(){const visible=groups.filter(g=>matches(g.name,...(g.tags||[]))||g.items.some(x=>matches(x.title,x.url,x.note,...(x.tags||[]))));$('#contentArea').innerHTML=visible.length?visible.map(g=>{let groupMatches=matches(g.name,...(g.tags||[]));let items=g.items.filter(x=>groupMatches||matches(x.title,x.url,x.note,...(x.tags||[])));return `<div class="card"><div class="grouphead">${g.id!=='inbox'?bulkCheckbox('group',g.id,'Chọn toàn bộ nhóm và các tab bên trong '+g.name):''}<div class="groupicon" style="color:${esc(g.color)}">${esc(g.icon)}</div><div class="rowtext"><b>${esc(g.name)}</b><small>${g.items.length} tab · Tạo ${timeLabel(g.createdAt)}${g.tags?.length?` · <span class="tags">${esc(g.tags.map(t=>'#'+t).join(' '))}</span>`:''}</small></div><div class="rowactions"><button data-action="open-group" data-group="${esc(g.id)}">Mở tất cả ↗</button><button data-action="edit-group" data-group="${esc(g.id)}">Sửa</button>${g.id!=='inbox'?`<button data-action="delete-group" data-group="${esc(g.id)}">Xóa</button>`:''}</div></div>${items.map(x=>`<div class="row">${bulkCheckbox('item',x.id,'Chọn tab '+x.title)}<div class="favicon">◈</div><div class="rowtext"><div class="rowtitle">${esc(x.title)}</div><div class="rowurl">${esc(x.url)} · Đã lưu ${timeLabel(x.createdAt)}${x.tags?.length?` · <span class="tags">${esc(x.tags.map(t=>'#'+t).join(' '))}</span>`:''}</div>${x.note?`<div class="item-note">${esc(x.note)}</div>`:''}</div><div class="rowactions"><button data-action="open-item" data-group="${esc(g.id)}" data-item="${esc(x.id)}">Mở ↗</button><button data-action="detail-item" data-group="${esc(g.id)}" data-item="${esc(x.id)}">Chi tiết</button><button data-action="move-item" data-group="${esc(g.id)}" data-item="${esc(x.id)}">Chuyển</button><button data-action="delete-item" data-group="${esc(g.id)}" data-item="${esc(x.id)}">Xóa</button></div></div>`).join('')||'<div class="row muted">Chưa có tab trong nhóm này.</div>'}</div>`}).join(''):'<div class="empty"><b>Chưa có nhóm phù hợp</b>Tạo nhóm hoặc lưu tab để bắt đầu.</div>'}
function renderSearch(){
 if(!query.trim()){$('#contentArea').innerHTML='<div class="empty"><b>Tìm mọi thứ ở một nơi</b>Nhập tên, URL, ghi chú hoặc tag để bắt đầu. Nội dung trang không được lập chỉ mục.</div>';return}
 const result=SearchTools.find({query,tabs,groups,snapshots,presets});
 const section=(title,rows)=>rows.length?`<div class="sectionhead"><div><h2>${title}</h2></div><span class="sectioncount">${rows.length} kết quả</span></div><div class="card">${rows.join('')}</div>`:'';
 const open=result.open.map(t=>`<div class="row"><div class="favicon">◫</div><div class="rowtext"><div class="rowtitle">${esc(t.title||t.url)}</div><div class="rowurl">${esc(t.url)}</div></div><span class="badge">Đang mở${t.discarded?' · Đã nghỉ':''}</span><div class="rowactions"><button data-action="switch" data-id="${t.id}">Đến tab ↗</button></div></div>`);
 const groupRows=result.groups.map(g=>`<div class="row"><div class="favicon" style="color:${esc(g.color)}">${esc(g.icon)}</div><div class="rowtext"><div class="rowtitle">${esc(g.name)}</div><div class="rowurl">${g.items.length} tab · ${esc((g.tags||[]).map(t=>'#'+t).join(' '))}</div></div><span class="badge">Nhóm</span><div class="rowactions"><button data-action="show-saved-search" data-query="${esc(g.name)}">Xem nhóm ↗</button></div></div>`);
 const items=result.items.map(({group:g,item:x})=>`<div class="row"><div class="favicon">◈</div><div class="rowtext"><div class="rowtitle">${esc(x.title)}</div><div class="rowurl">${esc(x.url)} · ${esc(g.name)}${x.tags?.length?' · '+esc(x.tags.map(t=>'#'+t).join(' ')):''}</div>${x.note?`<div class="item-note">${esc(x.note)}</div>`:''}</div><span class="badge">Đã lưu</span><div class="rowactions"><button data-action="open-item" data-group="${esc(g.id)}" data-item="${esc(x.id)}">Mở ↗</button><button data-action="detail-item" data-group="${esc(g.id)}" data-item="${esc(x.id)}">Chi tiết</button></div></div>`);
 const sessions=result.sessions.map(s=>`<div class="row"><div class="favicon">◷</div><div class="rowtext"><div class="rowtitle">${esc(s.name)}</div><div class="rowurl">${s.windows.length} cửa sổ · Đã lưu ${timeLabel(s.createdAt)}</div></div><span class="badge">Phiên</span><div class="rowactions"><button data-action="restore-session" data-session="${esc(s.id)}">Xem & mở lại ↗</button></div></div>`);
 const presetRows=result.presets.map(p=>`<div class="row"><div class="favicon">⌁</div><div class="rowtext"><div class="rowtitle">${esc(p.name)}</div><div class="rowurl">${esc(p.domains.join(', '))}</div></div><span class="badge">Preset</span><div class="rowactions"><button data-action="preview-preset" data-preset="${esc(p.id)}">Xem & dọn ↗</button></div></div>`);
 $('#contentArea').innerHTML=section('Tab đang mở',open)+section('Nhóm liên quan',groupRows)+section('Tab đã lưu',items)+section('Phiên liên quan',sessions)+section('Preset liên quan',presetRows)||'<div class="empty"><b>Không tìm thấy kết quả</b>Thử từ khóa khác hoặc kiểm tra tag.</div>';
}
function renderTags(){
 const tags=SearchTools.collectTags(groups).filter(t=>!query.trim()||t.name.toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi').replace(/^#+/,'')));
 $('#contentArea').innerHTML=`<div class="session-intro"><div><b>Nhìn lại theo chủ đề</b><p>Nhóm và tab gắn tag được tính riêng; tab không tự kế thừa tag của nhóm.</p></div></div>`+(tags.length?`<div class="card">${tags.map(t=>`<div class="row"><div class="favicon">#</div><div class="rowtext"><div class="rowtitle">${esc(t.name)}</div><div class="rowurl">${t.groups} nhóm · ${t.items} tab</div></div><div class="rowactions"><button data-action="search-tag" data-tag="${esc(t.name)}">Xem liên quan ↗</button></div></div>`).join('')}</div>`:'<div class="empty"><b>Chưa có tag phù hợp</b>Thêm tag trong phần chỉnh sửa nhóm hoặc chi tiết tab.</div>');
}

function itemDetailDialog(group,item){
 showDialog(`<h2>Chi tiết tab đã lưu</h2><p>${esc(item.title)}<br>${esc(item.url)}</p><label class="field">Tag <small>(phân cách bằng dấu phẩy)</small><input name="tags" value="${esc((item.tags||[]).join(', '))}" placeholder="công việc, thiết kế"></label><label class="field">Ghi chú <small>(tối đa 4.000 ký tự)</small><textarea name="note" rows="4" maxlength="4000" placeholder="Vì sao bạn muốn lưu trang này?">${esc(item.note||'')}</textarea></label><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Lưu thay đổi</button></div>`,async(f,d)=>{
 const latest=await chrome.storage.local.get('groups');const current=(latest.groups||[]).find(g=>g.id===group.id)?.items.find(x=>x.id===item.id);if(!current)throw Error('Tab đã di chuyển hoặc không còn tồn tại; hãy mở lại chi tiết.');current.tags=OrganizeTools.tags(f.get('tags'));current.note=OrganizeTools.note(f.get('note'));await chrome.storage.local.set({groups:latest.groups});d.close();await load();notify('Đã lưu chi tiết tab.');
 });
}
function moveItemDialog(group,item){
 const choices=groups.filter(g=>g.id!==group.id);if(!choices.length){notify('Hãy tạo thêm nhóm trước khi chuyển.');return}
 showDialog(`<h2>Chuyển tab đã lưu</h2><p>Chuyển “${esc(item.title)}” sang nhóm khác. Tag và ghi chú được giữ nguyên; tab đang mở không thay đổi.</p><label class="field">Nhóm đích<select name="target" required>${choices.map(g=>`<option value="${esc(g.id)}">${esc(g.icon)} ${esc(g.name)}</option>`).join('')}</select></label><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Chuyển tab</button></div>`,async(f,d)=>{const latest=await chrome.storage.local.get('groups');OrganizeTools.move(latest.groups||[],group.id,item.id,f.get('target'));await chrome.storage.local.set({groups:latest.groups});d.close();await load();notify('Đã chuyển tab sang nhóm mới.')});
}

function bulkCheckbox(type,itemId,label){const k=BulkTools.key(type,itemId);return `<input type="checkbox" data-bulk-key="${esc(k)}" aria-label="${esc(label)}" ${bulkSelected.has(k)?'checked':''}>`}
function bulkResult(title,results){
 const success=results.filter(x=>!x.error).length;
 showDialog(`<h2>${esc(title)}</h2><p>Thành công ${success}/${results.length}. ${success<results.length?'Các mục lỗi được liệt kê bên dưới; bạn có thể kiểm tra và thử lại.':''}</p><div class="dialoglist">${results.map(x=>`<div>${x.error?'⚠':'✓'} ${esc(x.name)}${x.error?' · '+esc(x.error):''}</div>`).join('')}</div><div class="dialogactions"><button value="cancel" class="secondary">Đóng</button></div>`,async(_f,d)=>d.close());
}
function bulkDeleteDialog(){
 const keys=[...bulkSelected];let plan;
 if(view==='saved')plan=BulkTools.savedPlan(groups,keys);
 else if(view==='sessions'){const ids=new Set(BulkTools.selectedIds(keys,'session'));plan=snapshots.filter(s=>ids.has(s.id)).map(s=>({type:'session',id:s.id,name:s.name}))}
 else if(view==='trash')plan=BulkTools.trashPlan(trash,keys).map(t=>({type:'trash',id:t.id,name:t.value.name||t.value.title||t.value.url}));
 else return;if(!plan.length){notify('Các mục đã chọn không còn tồn tại.');return}
 const permanent=view==='trash';showDialog(`<h2>${permanent?'Xóa vĩnh viễn':'Chuyển vào thùng rác'}?</h2><p>${permanent?'Các mục sẽ không thể khôi phục từ thùng rác.':'Tab đang mở không bị ảnh hưởng. Chọn nhóm sẽ chuyển toàn bộ nhóm, kể cả tab bị ẩn bởi tìm kiếm. Nếu chọn cả nhóm và tab bên trong, nhóm chỉ được xử lý một lần.'} Sẽ xử lý ${plan.length} mục.</p><div class="dialoglist">${plan.map(x=>`<div>• ${esc(x.name)}</div>`).join('')}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="danger-soft">${permanent?'Xóa vĩnh viễn':'Chuyển vào thùng rác'}</button></div>`,async(_f,d)=>{
 const results=[];for(const x of plan){try{if(x.type==='trash'){const k=TrashTools.prefix+x.id;const current=await chrome.storage.local.get(k);if(!current[k])throw Error('Mục không còn tồn tại.');await chrome.storage.local.remove(k)}else await TrashTools.move(chrome,x.type,x.id,x.groupId||null,id);results.push({name:x.name})}catch(e){results.push({name:x.name,error:e.message})}}
 bulkSelected.clear();d.close();await load();bulkResult('Kết quả thao tác',results);
 });
}
function bulkRestoreDialog(){
 const plan=BulkTools.trashPlan(trash,[...bulkSelected]);if(!plan.length){notify('Các mục đã chọn không còn tồn tại.');return}
 showDialog(`<h2>Khôi phục dữ liệu?</h2><p>Khôi phục ${plan.length} mục. Nhóm sẽ được khôi phục trước tab thuộc nhóm; các mục xung đột sẽ được giữ trong thùng rác.</p><div class="dialoglist">${plan.map(t=>`<div>• ${esc(t.value.name||t.value.title||t.value.url)}</div>`).join('')}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Khôi phục</button></div>`,async(_f,d)=>{const results=[];for(const t of plan){const name=t.value.name||t.value.title||t.value.url;try{await TrashTools.restore(chrome,t.id);results.push({name})}catch(e){results.push({name,error:e.message})}}bulkSelected.clear();d.close();await load();bulkResult('Kết quả khôi phục',results)});
}
function bulkOpenDialog(){
 const plan=BulkTools.openPlan(groups,[...bulkSelected]);if(!plan.length){notify('Không có tab đã lưu để mở.');return}
 showDialog(`<h2>Mở các tab đã chọn?</h2><p>Sẽ mở tối đa ${plan.length} tab trong cửa sổ hiện tại; Chrome có thể tải ngay. Nhóm được chọn bao gồm cả các tab đang ẩn bởi tìm kiếm. Bản lưu được giữ nguyên.</p><div class="dialoglist">${plan.map(x=>`<div>• ${esc(x.name)} · ${esc(x.url)}</div>`).join('')}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Mở ${plan.length} tab</button></div>`,async(_f,d)=>{
 const results=[];for(const x of plan){try{const latest=await chrome.storage.local.get('groups');const item=(latest.groups||[]).find(g=>g.id===x.groupId)?.items.find(i=>i.id===x.id);if(!item||item.url!==x.url)throw Error('Bản lưu đã thay đổi hoặc không còn tồn tại.');if(!validUrl(item.url))throw Error('URL không được hỗ trợ.');await chrome.tabs.create({url:item.url,active:false});results.push({name:x.name})}catch(e){results.push({name:x.name,error:e.message})}}
 bulkSelected.clear();d.close();await load();bulkResult('Kết quả mở tab',results);
 });
}
function bulkTagsDialog(){
 const plan=BulkTools.tagPlan(groups,[...bulkSelected]);if(!plan.length){notify('Các mục đã chọn không còn tồn tại.');return}
 showDialog(`<h2>Sửa tag hàng loạt</h2><p>Thao tác trên ${plan.length} mục được chọn. Chọn nhóm chỉ sửa tag của nhóm, không tự thay đổi tag các tab bên trong.</p><label class="field">Thao tác<select name="mode"><option value="add">Thêm tag</option><option value="remove">Gỡ tag</option></select></label><label class="field">Tag <small>(phân cách bằng dấu phẩy; tối đa 50 tag, mỗi tag 80 ký tự)</small><input name="tags" required placeholder="công việc, thiết kế"></label><div class="dialoglist">${plan.map(x=>`<div>• ${x.type==='group'?'Nhóm':'Tab'}: ${esc(x.name)}</div>`).join('')}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Áp dụng</button></div>`,async(f,d)=>{const latest=await chrome.storage.local.get('groups');const outcome=BulkTools.applyTags(latest.groups||[],plan,f.get('tags'),f.get('mode'));await chrome.storage.local.set({groups:outcome.groups});bulkSelected.clear();d.close();await load();bulkResult('Kết quả sửa tag',outcome.results)});
}

function bulkMoveDialog(){
 const plan=BulkTools.savedPlan(groups,[...bulkSelected]);if(!plan.length){notify('Các tab đã chọn không còn tồn tại.');return}if(plan.some(x=>x.type!=='item')){notify('Để chuyển tab, hãy bỏ chọn các nhóm và chỉ chọn tab.');return}if(groups.length<2){notify('Hãy tạo thêm nhóm đích.');return}
 showDialog(`<h2>Chuyển tab đã chọn</h2><p>Chuyển ${plan.length} bản lưu, giữ nguyên tag và ghi chú. Tab đang mở không thay đổi; tab đã ở nhóm đích sẽ được bỏ qua.</p><label class="field">Nhóm đích<select name="target" required>${groups.map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}</select></label><div class="dialoglist">${plan.map(x=>`<div>• ${esc(x.name)}</div>`).join('')}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Chuyển tab</button></div>`,async(f,d)=>{const target=f.get('target');const results=[];for(const x of plan){try{const latest=await chrome.storage.local.get('groups');OrganizeTools.move(latest.groups||[],x.groupId,x.id,target);await chrome.storage.local.set({groups:latest.groups});results.push({name:x.name})}catch(e){results.push({name:x.name,error:e.message})}}bulkSelected.clear();d.close();await load();bulkResult('Kết quả chuyển nhóm',results)});
}

function renderTrash(){
 const visible=trash.filter(t=>matches(t.value.name,t.value.title,t.value.url));const labels={group:'Nhóm',item:'Tab đã lưu',session:'Phiên'};
 $('#contentArea').innerHTML=`<div class="session-intro"><div><b>Một nơi để bạn xem lại</b><p>Chỉ chứa nhóm, tab đã lưu và phiên bị xóa từ phiên bản này. Không tự xóa theo thời gian; có trong file xuất.</p></div></div>`+(visible.length?visible.map(t=>`<div class="card"><div class="grouphead">${bulkCheckbox('trash',t.id,'Chọn mục '+(t.value.name||t.value.title||'thùng rác'))}<div class="groupicon">⌫</div><div class="rowtext"><b>${esc(t.value.name||t.value.title||t.value.url)}</b><small>${esc(labels[t.type]||'Dữ liệu')} · Chuyển vào thùng rác ${timeLabel(t.deletedAt)}${t.type==='item'?' · Nhóm gốc: '+esc(groups.find(g=>g.id===t.groupId)?.name||'không còn tồn tại'):''}</small></div><div class="rowactions"><button data-action="restore-trash" data-trash="${esc(t.id)}">Khôi phục</button><button data-action="delete-trash" data-trash="${esc(t.id)}">Xóa vĩnh viễn</button></div></div></div>`).join(''):'<div class="empty"><b>Thùng rác trống</b>Dữ liệu đã lưu chuyển vào đây có thể được khôi phục.</div>');
}
async function restoreTrash(trashId){try{await TrashTools.restore(chrome,trashId);await load();notify('Đã khôi phục dữ liệu.')}catch(e){await load();notify(e.message)}}
function deleteTrash(trashId){confirmAction('Xóa vĩnh viễn?', 'Dữ liệu này sẽ không thể khôi phục từ thùng rác. Tab đang mở không bị ảnh hưởng.',async()=>{await chrome.storage.local.remove(TrashTools.prefix+trashId);notify('Đã xóa vĩnh viễn.')})}

const statusLabel={queued:'Chưa xử lý',closing:'Không rõ đã đóng hay chưa',closed:'Đã đóng',close_failed:'Không đóng được',skipped:'Đã bỏ qua',opening:'Không rõ đã mở lại hay chưa',opened:'Đã mở lại',open_failed:'Không mở lại được'};
function renderHistory(){
 const visible=batches.filter(b=>matches(b.source,...b.items.flatMap(x=>[x.title,x.url])));
 $('#contentArea').innerHTML=`<div class="session-intro"><div><b>Những lượt lưu & đóng</b><p>Nhật ký được lưu trên thiết bị và có trong file sao lưu. Trạng thái không rõ cần kiểm tra thủ công.</p></div></div>`+(visible.length?visible.map(b=>`<div class="card"><div class="grouphead"><div class="groupicon">↺</div><div class="rowtext"><b>${esc(b.source)}</b><small>${timeLabel(b.createdAt)} · ${b.items.length} tab · ${b.items.filter(x=>x.status==='closed').length} có thể mở lại</small></div><div class="rowactions"><button data-action="view-batch" data-batch="${esc(b.id)}">Xem chi tiết ↗</button><button data-action="delete-batch" data-batch="${esc(b.id)}">Xóa lịch sử</button></div></div></div>`).join(''):'<div class="empty"><b>Chưa có lịch sử phù hợp</b>Các lượt lưu & đóng mới sẽ xuất hiện ở đây.</div>');
}
function viewBatch(batchId){
 const b=batches.find(x=>x.id===batchId);if(!b){notify('Lượt dọn không còn tồn tại.');return}
 showDialog(`<h2>Chi tiết lượt dọn</h2><p>${esc(b.source)} · ${timeLabel(b.createdAt)}. Chỉ tab xác nhận đã đóng mới được chọn mở lại. ${b.imported?'Lượt này được nhập từ sao lưu; tab có thể đã được mở lại trên thiết bị khác. ':''}Trang sẽ tải lại; trạng thái chưa lưu không được khôi phục. Không mở cùng lúc từ hai cửa sổ Tabspace.</p><div class="dialoglist session-picker">${b.items.map((t,i)=>`<label>${t.status==='closed'?`<input type="checkbox" name="tab" value="${i}" checked>`:'<span>•</span>'}<span>${esc(t.title)}<small>${esc(t.url)} · ${esc(statusLabel[t.status]||'Trạng thái không rõ')}</small></span></label>`).join('')}</div><div class="dialogactions"><button value="cancel" class="secondary">Đóng</button><button class="primary" ${b.items.some(t=>t.status==='closed')?'':'disabled'}>Mở lại đã chọn</button></div>`,async(f,d)=>{const indexes=f.getAll('tab').map(Number);if(!indexes.length)throw Error('Hãy chọn ít nhất một tab.');const result=await BatchTools.reopen(chrome,BatchTools.prefix+batchId,indexes);d.close();await load();notify(`Đã mở lại ${result.opened} tab.${result.failed?` Không mở được ${result.failed} tab.`:''}${result.stopped?' Bị gián đoạn; hãy kiểm tra lịch sử và tab đang mở.':''}`)});
}
function deleteBatch(batchId){confirmAction('Xóa lịch sử lượt này?','Không xóa nhóm hoặc tab đã lưu, nhưng sẽ không còn mở lại từ lịch sử này.',async()=>{await chrome.storage.local.remove(BatchTools.prefix+batchId);notify('Đã xóa lịch sử.')})}

function renderPresets(){
 const visible=presets.filter(p=>matches(p.name,...p.domains,...(p.paths||[]),...(p.exactUrls||[])));
 $('#contentArea').innerHTML=`<div class="session-intro"><div><b>Dọn theo cách của bạn</b><p>Nhận diện theo tên miền hoặc URL, có ngoại lệ. Luôn xem trước và xác nhận; không tự đóng.</p></div><button class="primary" data-action="new-preset">＋ Tạo preset</button></div>`+(visible.length?visible.map(p=>{const g=groups.find(x=>x.id===p.groupId);return `<div class="card"><div class="grouphead"><div class="groupicon">⌁</div><div class="rowtext"><b>${esc(p.name)}</b><small>${esc([...p.domains,...(p.paths||[]),...(p.exactUrls||[])].join(', '))}${p.subdomains?' · Bao gồm tên miền con':''}</small><small>${g?'Lưu vào: '+esc(g.name):'Nhóm đích không còn tồn tại — hãy sửa preset'}</small></div><div class="rowactions"><button data-action="preview-preset" data-preset="${esc(p.id)}">Xem & dọn ↗</button><button data-action="edit-preset" data-preset="${esc(p.id)}">Sửa</button><button data-action="delete-preset" data-preset="${esc(p.id)}">Xóa</button></div></div></div>`}).join(''):'<div class="empty"><b>Chưa có preset phù hợp</b>Tạo preset để tìm nhanh các trang cùng chủ đề.</div>');
}
function presetDialog(p){
 if(!groups.length){notify('Hãy tạo nhóm đích trước khi tạo preset.');return}
 showDialog(`<h2>${p?'Sửa preset':'Tạo preset'}</h2><p>Quy tắc bao gồm chỉ chọn ứng viên; ngoại lệ luôn được bỏ qua. URL không phân biệt được tài khoản công việc và cá nhân. Bản này không tự đóng tab.</p><label class="field">Tên preset<input name="name" required maxlength="80" value="${esc(p?.name||'')}" placeholder="Ví dụ: Công việc"></label><label class="field">Tên miền <small>(mỗi dòng một tên miền)</small><textarea name="domains" rows="3" placeholder="github.com&#10;app.slack.com">${esc(p?.domains.join('\n')||'')}</textarea></label><details class="preset-advanced"><summary>URL và ngoại lệ <span>Tùy chọn</span></summary><p>Mỗi dòng một URL đầy đủ. Đường dẫn khớp chính trang đó và các đường dẫn con, phân biệt http/https, cổng và chữ hoa/thường; không xét query hoặc fragment. URL chính xác xét cả query và fragment.</p><label class="field">Bao gồm đường dẫn<textarea name="paths" rows="2" placeholder="https://github.com/company">${esc((p?.paths||[]).join('\n'))}</textarea></label><label class="field">Bao gồm URL chính xác<textarea name="exactUrls" rows="2" placeholder="https://example.com/page?x=1">${esc((p?.exactUrls||[]).join('\n'))}</textarea></label><label class="field">Loại trừ tên miền<textarea name="excludeDomains" rows="2" placeholder="personal.example.com">${esc((p?.excludeDomains||[]).join('\n'))}</textarea></label><label class="field">Loại trừ đường dẫn<textarea name="excludePaths" rows="2" placeholder="https://github.com/personal">${esc((p?.excludePaths||[]).join('\n'))}</textarea></label><label class="field">Loại trừ URL chính xác<textarea name="excludeUrls" rows="2">${esc((p?.excludeUrls||[]).join('\n'))}</textarea></label></details><label class="checkline"><input type="checkbox" name="subdomains" ${p?.subdomains?'checked':''}> Bao gồm tên miền con (áp dụng cả ngoại lệ tên miền)</label><label class="field">Nhóm đích<select name="group" required><option value="">Chọn nhóm đích</option>${groups.map(g=>`<option value="${esc(g.id)}" ${p?.groupId===g.id?'selected':''}>${esc(g.icon)} ${esc(g.name)}</option>`).join('')}</select></label><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Lưu preset</button></div>`,async(f,d)=>{
 const name=String(f.get('name')).trim();if(!name)throw Error('Vui lòng nhập tên preset.');const parse=(field,fn)=>[...new Set(String(f.get(field)||'').split(/\n+/).map(x=>x.trim()).filter(Boolean).map(x=>fn(x)))];const domains=parse('domains',PresetTools.normalizeDomain),paths=parse('paths',x=>PresetTools.normalizeUrl(x,true)),exactUrls=parse('exactUrls',PresetTools.normalizeUrl),excludeDomains=parse('excludeDomains',PresetTools.normalizeDomain),excludePaths=parse('excludePaths',x=>PresetTools.normalizeUrl(x,true)),excludeUrls=parse('excludeUrls',PresetTools.normalizeUrl);if(!domains.length&&!paths.length&&!exactUrls.length)throw Error('Vui lòng thêm ít nhất một quy tắc bao gồm.');if([domains,paths,exactUrls,excludeDomains,excludePaths,excludeUrls].some(a=>a.length>1000))throw Error('Mỗi loại tối đa 1.000 quy tắc.');const groupId=f.get('group');const latest=await chrome.storage.local.get(['groups','presets']);if(!(latest.groups||[]).some(g=>g.id===groupId))throw Error('Nhóm đích không còn tồn tại.');let list=latest.presets||[];const preset={id:p?.id||id(),name,domains,paths,exactUrls,excludeDomains,excludePaths,excludeUrls,subdomains:f.has('subdomains'),groupId,createdAt:p?.createdAt||Date.now()};if(p&&!list.some(x=>x.id===p.id))throw Error('Preset không còn tồn tại.');list=p?list.map(x=>x.id===p.id?preset:x):[...list,preset];await chrome.storage.local.set({presets:list});d.close();await load();notify('Đã lưu preset.');
 });
}
async function previewPreset(presetId){
 const p=presets.find(x=>x.id===presetId);if(!p){notify('Preset không còn tồn tại.');return}const group=groups.find(g=>g.id===p.groupId);if(!group){notify('Nhóm đích không còn tồn tại; hãy sửa preset.');return}const all=(await chrome.tabs.query({})).filter(t=>!t.incognito&&PresetTools.included(t.url,p));const excludedTabs=all.filter(t=>PresetTools.excluded(t.url,p));const fresh=all.filter(t=>!PresetTools.excluded(t.url,p));const eligible=fresh.filter(t=>!PresetTools.reason(t));const protectedTabs=fresh.filter(t=>PresetTools.reason(t));
 showDialog(`<h2>${esc(p.name)} · Xem trước</h2><p>Nhóm đích: <b>${esc(group.name)}</b>. Chỉ các tab được chọn mới được lưu và đóng. Form chưa lưu và tác vụ nền có thể bị mất; không thể phát hiện mọi trường hợp.</p><div class="dialoglist session-picker">${eligible.length?eligible.map(t=>`<label><input type="checkbox" name="tab" value="${t.id}" checked><span>${esc(t.title||t.url)}<small>${esc(t.url)}</small></span></label>`).join(''):'Không có tab đủ điều kiện.'}${protectedTabs.length?`<b>Bỏ qua (${protectedTabs.length})</b>${protectedTabs.map(t=>`<div>${esc(t.title||t.url)} · ${esc(PresetTools.reason(t))}</div>`).join('')}`:''}${excludedTabs.length?`<b>Loại trừ theo quy tắc (${excludedTabs.length})</b>${excludedTabs.map(t=>`<div>${esc(t.title||t.url)} · ${esc(t.url)}</div>`).join('')}`:''}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="danger-soft" ${eligible.length?'':'disabled'}>Lưu & đóng đã chọn</button></div>`,async(f,d)=>{
 const ids=new Set(f.getAll('tab').map(Number));if(!ids.size)throw Error('Hãy chọn ít nhất một tab.');const latest=await chrome.storage.local.get(['groups','presets']);const currentPreset=(latest.presets||[]).find(x=>x.id===presetId);const target=(latest.groups||[]).find(x=>x.id===p.groupId);if(!currentPreset||JSON.stringify(currentPreset)!==JSON.stringify(p))throw Error('Preset đã thay đổi; hãy xem trước lại.');if(!target)throw Error('Nhóm đích không còn tồn tại.');let prepared=[],skipped=0;
 for(const original of eligible.filter(t=>ids.has(t.id))){try{const t=await chrome.tabs.get(original.id);if(t.url!==original.url||PresetTools.reason(t)||!PresetTools.matchesPreset(t.url,p)){skipped++;continue}prepared.push({id:t.id,url:t.url,item:{id:id(),url:t.url,title:t.title||t.url,createdAt:Date.now(),tags:[]}})}catch{skipped++}}
 if(!prepared.length)throw Error('Các tab đã thay đổi hoặc được bảo vệ. Hãy xem trước lại.');const beforeWrite=await chrome.storage.local.get(['groups','presets']);const finalPreset=(beforeWrite.presets||[]).find(x=>x.id===presetId);const finalTarget=(beforeWrite.groups||[]).find(x=>x.id===p.groupId);if(!finalTarget||!finalPreset||JSON.stringify(finalPreset)!==JSON.stringify(p))throw Error('Preset hoặc nhóm đã thay đổi; hãy xem trước lại.');finalTarget.items.unshift(...prepared.map(x=>x.item));await chrome.storage.local.set({groups:beforeWrite.groups});let result;try{result=await BatchTools.closeSaved(chrome,prepared.map(e=>({tabId:e.id,url:e.url,item:e.item})),`Preset: ${p.name}`,id,t=>!PresetTools.reason(t))}catch(e){d.close();await load();notify('Đã lưu tab nhưng không thể ghi lịch sử; không đóng tab nào.');return}
 const closed=result.batch.items.filter(x=>x.status==='closed').length;d.close();await load();notify(`Đã lưu ${prepared.length} tab, đóng ${closed}. ${result.stopped?'Lượt dọn bị gián đoạn; xem Lịch sử dọn.':`Xem chi tiết tại Lịch sử dọn.${skipped?` Bỏ qua ${skipped} tab đã thay đổi.`:''}`}`);
 });
}
function deletePreset(presetId){const p=presets.find(x=>x.id===presetId);if(!p)return;confirmAction('Xóa preset?',`Xóa “${p.name}”; nhóm và tab đã lưu không bị ảnh hưởng.`,async()=>{const latest=await chrome.storage.local.get('presets');await chrome.storage.local.set({presets:(latest.presets||[]).filter(x=>x.id!==presetId)});notify('Đã xóa preset.')})}

function renderSessions(){
  const visible=snapshots.filter(s=>matches(s.name,...s.windows.flatMap(w=>w.flatMap(t=>[t.title,t.url]))));
  $('#contentArea').innerHTML=`<div class="session-intro"><div><b>Giữ lại một khoảnh khắc làm việc</b><p>Lưu thủ công các tab web đang mở, không đóng tab nào.</p></div><button class="primary" data-action="capture-session">＋ Lưu phiên hiện tại</button></div>`+(visible.length?visible.map(s=>`<div class="card"><div class="grouphead">${bulkCheckbox('session',s.id,'Chọn phiên '+s.name)}<div class="groupicon">◷</div><div class="rowtext"><b>${esc(s.name)}</b><small>Đã lưu ${timeLabel(s.createdAt)} · ${s.windows.length} cửa sổ · ${s.windows.reduce((n,w)=>n+w.length,0)} tab</small></div><div class="rowactions"><button data-action="restore-session" data-session="${esc(s.id)}">Xem & mở lại ↗</button><button data-action="delete-session" data-session="${esc(s.id)}">Xóa</button></div></div>${s.windows.map((w,i)=>`<div class="session-window"><b>Cửa sổ ${i+1}</b><span>${w.length} tab</span><div>${w.slice(0,3).map(t=>esc(t.title)).join(' · ')}${w.length>3?' …':''}</div></div>`).join('')}</div>`).join(''):'<div class="empty"><b>Chưa có phiên phù hợp</b>Lưu phiên hiện tại để quay lại sau.</div>');
}
function captureSession(){
  showDialog(`<h2>Lưu phiên hiện tại</h2><p>Lưu các tab web trong cửa sổ thông thường. Không đóng hay thay đổi các tab. Trang Chrome, ẩn danh và trang không được hỗ trợ sẽ bị bỏ qua.</p><label class="field">Tên phiên<input name="name" required maxlength="80" placeholder="Ví dụ: Nghiên cứu hôm nay"></label><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Lưu phiên</button></div>`,async(f,d)=>{
    const name=String(f.get('name')).trim();if(!name)throw Error('Vui lòng nhập tên phiên.');
    const current=(await chrome.tabs.query({})).filter(t=>!isDashboard(t.url));
    const {snapshot,skipped}=SnapshotTools.capture(current,name,Date.now(),id);
    const count=snapshot.windows.reduce((n,w)=>n+w.length,0);if(!count)throw Error('Không có tab web nào có thể lưu.');
    const latest=await chrome.storage.local.get('snapshots');await chrome.storage.local.set({snapshots:[snapshot,...(latest.snapshots||[])]});
    d.close();await load();notify(`Đã lưu ${count} tab trong ${snapshot.windows.length} cửa sổ.${skipped?` Bỏ qua ${skipped} tab không hỗ trợ hoặc ẩn danh.`:''}`);
  });
}
function restoreSession(sessionId){
  const s=snapshots.find(x=>x.id===sessionId);if(!s){notify('Phiên không còn tồn tại.');return}
  showDialog(`<h2>Xem & mở lại phiên</h2><p>Chọn tab cần mở. Mỗi cửa sổ được chọn sẽ mở thành một cửa sổ Chrome mới; trang có thể tải ngay. Không khôi phục dữ liệu chưa lưu, lịch sử điều hướng hay nhóm Chrome.</p><div class="dialoglist session-picker">${s.windows.map((w,i)=>`<b>Cửa sổ ${i+1}</b>${w.map((t,j)=>`<label><input type="checkbox" name="tab" value="${i}:${j}" checked> <span>${esc(t.title)}<small>${esc(t.url)}</small></span></label>`).join('')}`).join('')}</div><div class="dialogactions"><button value="cancel" class="secondary">Hủy</button><button class="primary">Mở tab đã chọn</button></div>`,async(f,d)=>{
    const selected=new Set(f.getAll('tab'));if(!selected.size)throw Error('Hãy chọn ít nhất một tab.');
    d.close();let opened=0,failed=0,pinFailed=0;
    for(let i=0;i<s.windows.length;i++){
      const items=s.windows[i].filter((_,j)=>selected.has(`${i}:${j}`));if(!items.length)continue;
      let win;try{win=await chrome.windows.create({url:items[0].url});opened++;if(items[0].pinned&&win.tabs?.[0]?.id){try{await chrome.tabs.update(win.tabs[0].id,{pinned:true})}catch{pinFailed++}}}catch{failed+=items.length;continue}
      for(const item of items.slice(1)){try{await chrome.tabs.create({windowId:win.id,url:item.url,active:false,pinned:item.pinned});opened++}catch{failed++}}
    }
    await load();notify(`Đã mở ${opened} tab.${failed?` Không mở được ${failed} tab.`:''}${pinFailed?` Không ghim được ${pinFailed} tab.`:''} Bản lưu được giữ nguyên.`);
  });
}
function deleteSession(sessionId){const s=snapshots.find(x=>x.id===sessionId);if(!s)return;confirmAction('Chuyển phiên vào thùng rác?',`Phiên “${s.name}” sẽ được chuyển vào thùng rác; tab đang mở không bị ảnh hưởng.`,async()=>{await TrashTools.move(chrome,'session',sessionId,null,id);notify('Đã chuyển phiên vào thùng rác.')})}

function renderSettings(){$('#contentArea').innerHTML=`<div class="card settingscard"><h2>Dữ liệu của bạn</h2><p>Dữ liệu được lưu trong Chrome trên thiết bị này. Hãy xuất bản sao lưu trước khi gỡ extension hoặc xóa profile. File có thể chứa URL và tag nhạy cảm. File xuất gồm nhóm, phiên, preset, thùng rác và lịch sử dọn. Các dữ liệu này chỉ nằm trên thiết bị trừ khi bạn xuất file.</p><div class="settingsactions"><button class="primary" data-action="export">↓ Xuất dữ liệu JSON</button><button class="secondary" data-action="import">↑ Nhập dữ liệu JSON</button><input id="importFile" type="file" accept="application/json,.json" hidden></div></div><div class="card settingscard"><h2>Phiên bản thử nghiệm · 0.14</h2><p>Phiên bản này chưa có tự động hóa, lịch, preset tự động, snapshot tự động hoặc đồng bộ. Không sử dụng như bản sao lưu duy nhất.</p></div>`}
function render(){ $('#sideOpen').textContent=$('#statOpen').textContent=tabs.length;$('#sideSessions').textContent=snapshots.length;$('#sideHistory').textContent=batches.length;$('#sideTrash').textContent=trash.length;$('#sidePresets').textContent=presets.length;$('#sideTags').textContent=SearchTools.collectTags(groups).length;$('#sideDuplicates').textContent=DuplicateTools.find(tabs).length;const n=groups.reduce((s,g)=>s+g.items.length,0);$('#sideSaved').textContent=$('#statSaved').textContent=n;$('#statGroups').textContent=groups.length;$('#sideGroups').innerHTML=groups.map(g=>`<button class="sidegroup" data-action="goto-group" data-group="${esc(g.id)}"><span style="color:${esc(g.color)}">${esc(g.icon)}</span>${esc(g.name)}</button>`).join('');document.querySelectorAll('.nav[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const labels={search:['Tìm tất cả','Tìm đồng thời trong tab, nhóm, phiên và preset.'],tags:['Tag','Các nhãn của nhóm và tab đã lưu.'],open:['Tab đang mở','Mọi trang bạn đang mở, gọn gàng ở một nơi.'],duplicates:['Tab trùng URL','Xem các tab có cùng địa chỉ và chọn những tab cần xử lý.'],saved:['Nhóm đã lưu','Những trang quan trọng, sẵn sàng khi bạn cần.'],trash:['Thùng rác','Khôi phục dữ liệu đã lưu hoặc xóa vĩnh viễn.'],history:['Lịch sử dọn','Xem kết quả từng lượt lưu và đóng.'],presets:['Preset dọn tab','Tìm các trang liên quan và tự quyết định điều gì xảy ra.'],sessions:['Phiên đã lưu','Lưu lại các cửa sổ để quay lại khi bạn cần.'],settings:['Cài đặt & sao lưu','Kiểm soát dữ liệu và không gian của bạn.']};$('#title').innerHTML=esc(labels[view][0])+' <span>✳</span>';$('#crumb').textContent=labels[view][0];$('#subtitle').textContent=labels[view][1];$('#eyebrow').textContent=view==='saved'?'THƯ VIỆN CỦA BẠN':'KHÔNG GIAN LÀM VIỆC';$('.toolbar').classList.toggle('hidden',view==='settings');$('#selectAll').classList.toggle('hidden',view!=='open'&&view!=='duplicates');$('#saveSelected').classList.toggle('hidden',view!=='open'&&view!=='duplicates');$('#selectionBar').classList.toggle('hidden',(view!=='open'&&view!=='duplicates')||selected.size===0);$('#selectedCount').textContent=`Đã chọn ${selected.size} tab`;$('#saveSelected').disabled=!selected.size;const hasBulk=['saved','sessions','trash'].includes(view);$('#bulkBar').classList.toggle('hidden',!hasBulk);$('#bulkCount').textContent=`Đã chọn ${bulkSelected.size} mục`;$('#bulkDelete').disabled=!bulkSelected.size;$('#bulkDelete').textContent=view==='trash'?'Xóa vĩnh viễn':'Chuyển vào thùng rác';$('#bulkRestore').classList.toggle('hidden',view!=='trash');$('#bulkRestore').disabled=!bulkSelected.size;$('#bulkOpen').classList.toggle('hidden',view!=='saved');$('#bulkOpen').disabled=!bulkSelected.size;$('#bulkTags').classList.toggle('hidden',view!=='saved');$('#bulkTags').disabled=!bulkSelected.size;$('#bulkMove').classList.toggle('hidden',view!=='saved');$('#bulkMove').disabled=!bulkSelected.size;$('#bulkClear').disabled=!bulkSelected.size;if(view==='open')renderOpen();else if(view==='saved')renderSaved();else if(view==='duplicates')renderDuplicates();else if(view==='sessions')renderSessions();else if(view==='presets')renderPresets();else if(view==='history')renderHistory();else if(view==='trash')renderTrash();else if(view==='search')renderSearch();else if(view==='tags')renderTags();else renderSettings()}
function confirmAction(title,description,action){showDialog(`<h2>${esc(title)}</h2><p>${esc(description)}</p><div class="dialogactions"><button class="secondary" value="cancel">Hủy</button><button class="danger-soft">Xác nhận</button></div>`,async(_f,d)=>{await action();d.close();await load()})}
function validateImport(data){if(!data||data.format!=='tabspace-backup'||![1,2].includes(data.version)||!Array.isArray(data.groups))throw Error('File không đúng định dạng hoặc phiên bản không hỗ trợ.');if(data.groups.length>10000)throw Error('File chứa quá nhiều nhóm.');return data.groups.map(g=>{if(typeof g.name!=='string'||!Array.isArray(g.items)||g.items.length>100000)throw Error('Nhóm không hợp lệ.');return {id:id(),name:g.name.slice(0,80),icon:typeof g.icon==='string'?g.icon.slice(0,8):'✦',color:/^#[0-9a-f]{6}$/i.test(g.color)?g.color:'#7564d6',createdAt:Number(g.createdAt)||Date.now(),tags:OrganizeTools.importTags(g.tags),items:g.items.map(x=>{if(!validUrl(x.url)||typeof x.title!=='string')throw Error('File có tab không hợp lệ.');return{id:id(),url:x.url,title:x.title,createdAt:Number(x.createdAt)||Date.now(),tags:OrganizeTools.importTags(x.tags),note:OrganizeTools.note(x.note)}})}})}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.view){view=b.dataset.view;selected.clear();bulkSelected.clear();query='';$('#search').value='';render();return}if(b.id==='newGroup'||b.id==='newGroupSide'){groupDialog();return}if(b.id==='bulkSelectVisible'){document.querySelectorAll('[data-bulk-key]').forEach(x=>bulkSelected.add(x.dataset.bulkKey));render();return}if(b.id==='bulkClear'){bulkSelected.clear();render();return}if(b.id==='bulkDelete'){bulkDeleteDialog();return}if(b.id==='bulkRestore'){bulkRestoreDialog();return}if(b.id==='bulkMove'){bulkMoveDialog();return}if(b.id==='bulkOpen'){bulkOpenDialog();return}if(b.id==='bulkTags'){bulkTagsDialog();return}if(b.id==='refresh'){await load();notify('Đã làm mới.');return}if(b.id==='selectAll'){document.querySelectorAll('[data-select]').forEach(x=>selected.add(Number(x.dataset.select)));render();return}if(b.id==='clearSelection'){selected.clear();render();return}if(b.id==='saveSelected'||b.id==='saveClose'){saveDialog(b.id==='saveClose');return}if(b.dataset.action==='global-search'){view='search';render();$('#search').focus();return}if(b.dataset.action==='search-tag'){view='search';query='#'+b.dataset.tag;$('#search').value=query;render();return}if(b.dataset.action==='show-saved-search'){view='saved';query=b.dataset.query||'';$('#search').value=query;render();return}if(b.dataset.action==='restore-trash'){await restoreTrash(b.dataset.trash);return}if(b.dataset.action==='delete-trash'){deleteTrash(b.dataset.trash);return}if(b.dataset.action==='view-batch'){viewBatch(b.dataset.batch);return}if(b.dataset.action==='delete-batch'){deleteBatch(b.dataset.batch);return}if(b.dataset.action==='new-preset'){presetDialog();return}if(b.dataset.action==='edit-preset'){presetDialog(presets.find(p=>p.id===b.dataset.preset));return}if(b.dataset.action==='preview-preset'){await previewPreset(b.dataset.preset);return}if(b.dataset.action==='delete-preset'){deletePreset(b.dataset.preset);return}if(b.dataset.action==='capture-session'){captureSession();return}if(b.dataset.action==='restore-session'){restoreSession(b.dataset.session);return}if(b.dataset.action==='delete-session'){deleteSession(b.dataset.session);return}const a=b.dataset.action,g=groups.find(g=>g.id===b.dataset.group),item=g?.items.find(x=>x.id===b.dataset.item),tab=tabs.find(t=>t.id===Number(b.dataset.id));if(a==='goto-group'){view='saved';query=g.name;$('#search').value=query;render()}if(a==='switch'&&tab){await chrome.windows.update(tab.windowId,{focused:true});await chrome.tabs.update(tab.id,{active:true})}if(a==='discard'&&tab){if(tab.active||tab.pinned||tab.audible){notify('Tab đang xem, được ghim hoặc đang phát âm thanh được bảo vệ.');return}confirmAction('Cho tab nghỉ?','Trang sẽ tải lại khi mở; nội dung chưa lưu có thể bị mất.',async()=>{await chrome.tabs.discard(tab.id);notify('Đã cho tab nghỉ.')})}if(a==='close'&&tab){confirmAction('Đóng tab này?','Tab sẽ đóng mà không lưu. Nội dung chưa lưu trên trang có thể bị mất.',async()=>{await chrome.tabs.remove(tab.id);selected.delete(tab.id);notify('Đã đóng tab.')})}if(a==='edit-group'&&g)groupDialog(g);if(a==='delete-group'&&g)confirmAction('Chuyển nhóm vào thùng rác?',`Nhóm “${g.name}” và ${g.items.length} bản lưu sẽ được chuyển vào thùng rác. Preset dùng nhóm này sẽ cần nhóm đích hợp lệ; tab đang mở không thay đổi.`,async()=>{await TrashTools.move(chrome,'group',g.id,null,id);notify('Đã chuyển nhóm vào thùng rác.')});if(a==='open-item'&&item)await chrome.tabs.create({url:item.url});if(a==='open-group'&&g){if(!g.items.length){notify('Nhóm chưa có tab.');return}confirmAction('Mở tất cả tab?',`Chrome sẽ mở và có thể tải ${g.items.length} tab. Bản lưu được giữ nguyên.`,async()=>{let ok=0;for(const x of g.items){try{await chrome.tabs.create({url:x.url,active:false});ok++}catch{}}notify(`Đã mở ${ok}/${g.items.length} tab.`)})}if(a==='delete-item'&&item)confirmAction('Chuyển bản lưu vào thùng rác?','Tab đang mở không bị ảnh hưởng; bạn có thể khôi phục bản lưu sau.',async()=>{await TrashTools.move(chrome,'item',item.id,g.id,id);notify('Đã chuyển bản lưu vào thùng rác.')});if(a==='detail-item'&&item)itemDetailDialog(g,item);if(a==='move-item'&&item)moveItemDialog(g,item);if(a==='export'){const blob=new Blob([JSON.stringify(BackupTools.exportData(await chrome.storage.local.get(null)),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`tabspace-${new Date().toISOString().slice(0,10)}.json`;link.click();if(blob.size>10*1024*1024)notify('Đã xuất file lớn hơn 10 MB; phiên bản này chưa thể nhập file lớn như vậy.');setTimeout(()=>URL.revokeObjectURL(url),10000)}if(a==='import')$('#importFile').click();}catch(err){notify('Không thể thực hiện: '+err.message)}});
document.addEventListener('change',async e=>{if(e.target.matches('[data-bulk-key]')){const key=e.target.dataset.bulkKey;e.target.checked?bulkSelected.add(key):bulkSelected.delete(key);render();[...document.querySelectorAll('[data-bulk-key]')].find(x=>x.dataset.bulkKey===key)?.focus({preventScroll:true})}
if(e.target.matches('[data-select]')){const n=Number(e.target.dataset.select);e.target.checked?selected.add(n):selected.delete(n);render()}if(e.target.id==='importFile'&&e.target.files[0]){try{const file=e.target.files[0];if(file.size>10*1024*1024)throw Error('File lớn hơn 10 MB.');const backup=JSON.parse(await file.text());const imported=validateImport(backup);const importedSessions=SnapshotTools.validate(backup.snapshots ?? [],id);const extra=BackupTools.extras(backup,imported,id,validateImport,list=>SnapshotTools.validate(list,id));const importedPresets=PresetTools.validate(backup.presets ?? [],id,extra.groupMap);showDialog(`<h2>Nhập dữ liệu</h2><p>File có ${imported.length} nhóm và ${imported.reduce((n,g)=>n+g.items.length,0)} tab, ${importedSessions.length} phiên, ${importedPresets.length} preset, ${extra.trashCount} mục thùng rác và ${extra.batchCount} lượt lịch sử. Bản nhập tạo ID mới; dữ liệu trùng không tự gộp. Chế độ thay thế giữ lại thùng rác và lịch sử cũ rồi thêm dữ liệu từ file. Hãy xuất bản sao lưu trước khi thay thế.</p><label class="field">Cách nhập<select name="mode"><option value="merge">Thêm vào dữ liệu hiện có</option><option value="replace">Thay thế toàn bộ dữ liệu hiện có</option></select></label><div class="dialogactions"><button class="secondary" value="cancel">Hủy</button><button class="primary">Nhập dữ liệu</button></div>`,async(f,d)=>{if(f.get('mode')==='replace'&&!confirm('Thay thế sẽ xóa toàn bộ nhóm, tab, phiên và preset đã lưu hiện tại. Bạn đã sao lưu chưa?'))return;const replace=f.get('mode')==='replace';const latest=await chrome.storage.local.get(['groups','snapshots','presets']);const nextGroups=replace?imported:[...(latest.groups||[]),...imported];const nextSessions=replace?importedSessions:[...(latest.snapshots||[]),...importedSessions];const nextPresets=replace?importedPresets:[...(latest.presets||[]),...importedPresets];await chrome.storage.local.set({groups:nextGroups,snapshots:nextSessions,presets:nextPresets,...extra.records});d.close();await load();notify('Đã nhập dữ liệu.')})}catch(err){notify('Không nhập được: '+err.message)}e.target.value=''}});
$('#search').addEventListener('input',e=>{query=e.target.value;render()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)&&!$('#dialog').open){e.preventDefault();$('#search').focus()}});
