load().then(async()=>{const params=new URLSearchParams(location.search);const saveId=params.get('saveClose'),presetId=params.get('preset');if(saveId||presetId){history.replaceState(null,'',dashboardUrl);if(saveId){const tab=tabs.find(t=>t.id===Number(saveId));if(!tab||tab.incognito||!validUrl(tab.url)){notify('Tab không còn tồn tại hoặc không được hỗ trợ.');return}selected.add(tab.id);render();saveDialog(true)}else if(presetId){view='presets';render();await previewPreset(presetId)}}}).catch(e=>notify('Không tải được dữ liệu: '+e.message));
